      "actions": {
        "BIvhzgu4Bi6t171L": {
          "name": "Negar vantagem",
          "description": "Mialari não está desprevenido para flanquear criaturas de 10º nível ou inferior, ou criaturas de 10º nível ou inferior usando ataque surpresa."
        },
        "BiJxTD0UCp5DwYqu": {
          "name": "Esquiva ágil",
          "description": "Trigger Mialari é alvo de um ataque corpo a corpo ou à distância por um atacante que ela possa ver.\nEfeito Mialari ganha um bônus de circunstância de +2 na CA contra o ataque desencadeador."
        },
        "kg205YMOcrEz6XQw": {
          "name": "Legerdemônio de Combate à Distância",
          "description": "Mialari pode usar telecinesia para realizar ações de manipulação que usam a perícia Ladrão em um alcance de 30 pés (9 metros), mas ela sofre -2 de penalidade de circunstância em seu teste ao fazer isso."
        },
        "4RTJGyTlfqna9dXb": {
          "name": "Ataque furtivo",
          "description": "Mialari causa 2d6 de dano de precisão extra a criaturas fora de guarda."
        },
        "nnJ4kOGHM4Qct2PR": {
          "name": "Conjuração constante",
          "description": "Quando uma reação interromper a magia de Mialari, ela pode tentar um teste (simples, dc:15), evitando a interrupção em caso de sucesso."
        },
        "RwOAEo9R3fFzTJY7": {
          "name": "Ataque surpresa",
          "description": "Na primeira rodada de combate, as criaturas que ainda não agiram ficam fora de guarda para Mialari."
        },
        "SH0nk4BfgI1ur3oJ": {
          "name": "Golpe desequilibrado",
          "description": "As criaturas que Mialari atinge com um acerto crítico ficam desprevenidas contra seus ataques até o final de seu próximo turno."
        }
      },
